SELECT * FROM products
AND ( name ILIKE CONCAT('%', #{query}, '%') OR company ILIKE CONCAT('%', #{query}, '%') OR description ILIKE CONCAT('%', #{query}, '%') OR to_tsvector('english', coalesce(name,'') || ' ' || coalesce(company,'') || ' ' || coalesce(description,'') ) @@ websearch_to_tsquery('english', #{query}) )
ORDER BY CASE WHEN name ILIKE CONCAT('%', #{query}, '%') THEN 0 WHEN company ILIKE CONCAT('%', #{query}, '%') THEN 1 ELSE 2 END, created_at DESC LIMIT #{limit}

